<?php
require_once __DIR__.'/../includes/member.php';$user=require_login();if($user['role']==='admin')redirect('admin/dashboard.php');
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(($_POST['form_action']??'')==='profile'){$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$address=trim($_POST['address']??'');$gender=$_POST['gender']??'';$nik=trim($_POST['nik']??'');$duplicate=one('SELECT id FROM users WHERE email=? AND id<>?',[$email,$user['id']]);if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||$duplicate||!in_array($gender,['male','female'],true)){flash('Periksa kembali nama, email, dan gender. Email tidak boleh dipakai anggota lain.','error');}else{execute('UPDATE users SET name=?,email=?,address=?,gender=?,nik=?,updated_at=CURRENT_TIMESTAMP WHERE id=?',[$name,$email,$address,$gender,$nik,$user['id']]);foreach(['name'=>$name,'email'=>$email,'address'=>$address,'gender'=>$gender,'nik'=>$nik] as $key=>$value)$_SESSION['user'][$key]=$value;flash('Profil berhasil diperbarui.');}redirect('member/profile.php');}
    if(($_POST['form_action']??'')==='password'){$record=one('SELECT password FROM users WHERE id=?',[$user['id']]);$new=$_POST['new_password']??'';if(!password_verify($_POST['current_password']??'',$record['password']))flash('Kata sandi saat ini tidak sesuai.','error');elseif(strlen($new)<8||$new!==($_POST['confirm_password']??''))flash('Kata sandi baru minimal 8 karakter dan konfirmasi harus sama.','error');else{execute('UPDATE users SET password=?,updated_at=CURRENT_TIMESTAMP WHERE id=?',[password_hash($new,PASSWORD_DEFAULT),$user['id']]);flash('Kata sandi berhasil diganti.');}redirect('member/profile.php');}
}
$profile=one('SELECT * FROM users WHERE id=?',[$user['id']]);member_start('Profil Anggota',$user,''); ?>
<section class="member-section"><span class="member-kicker">AKUN ANGGOTA</span><h1>Profil</h1><div class="profile-card"><span class="profile-avatar profile-photo"><?php if(!empty($profile['photo_path'])):?><img src="<?=e(url($profile['photo_path']))?>" alt="Foto <?=e($profile['name'])?>"><?php else:?><?=e(strtoupper(substr($profile['name'],0,1)))?><?php endif;?></span><div class="profile-fields"><p><small>Nama panjang</small><b><?=e($profile['name'])?></b></p><p><small>Nomor member</small><b><?=e($profile['member_id'])?></b></p><p><small>Email</small><b><?=e($profile['email'])?></b></p><p><small>Alamat</small><b><?=e($profile['address']?:'Belum diisi')?></b></p><p><small>Gender</small><b><?=e(($profile['gender']??'')==='male'?'Laki-laki':(($profile['gender']??'')==='female'?'Perempuan':'Belum diisi'))?></b></p><p><small>Nomor KTP</small><b><?=e($profile['nik']?:'Belum diisi')?></b></p></div><div class="member-barcode profile-barcode"><span></span><small><?=e($profile['member_id'])?></small></div></div><div class="profile-actions"><details class="profile-editor"><summary class="member-see-all">Edit profile</summary><form class="member-form visible" method="post"><input type="hidden" name="form_action" value="profile"><label>Nama panjang<input name="name" value="<?=e($profile['name'])?>" required></label><label>Email<input type="email" name="email" value="<?=e($profile['email'])?>" required></label><label>Alamat<textarea name="address" rows="3"><?=e($profile['address']??'')?></textarea></label><label>Gender<select name="gender"><option value="female" <?=($profile['gender']==='female'?'selected':'')?>>Perempuan</option><option value="male" <?=($profile['gender']==='male'?'selected':'')?>>Laki-laki</option></select></label><label>Nomor KTP<input name="nik" value="<?=e($profile['nik']??'')?>" maxlength="32"></label><button type="submit">Simpan profil</button></form></details><details class="profile-editor"><summary class="member-see-all">Ganti password</summary><form class="member-form visible" method="post"><input type="hidden" name="form_action" value="password"><label>Password saat ini<input type="password" name="current_password" required></label><label>Password baru<input type="password" name="new_password" minlength="8" required></label><label>Konfirmasi password baru<input type="password" name="confirm_password" minlength="8" required></label><button type="submit">Simpan password</button></form></details></div></section><?php member_end(); ?>
